<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import {refreshAll} from '$app/navigation';
 import {command,display,permitted} from '#lib/client/api.ts';
 import type {AppData,Row} from '#lib/client/types.ts';
 import Icon from './Icon.svelte';
 import EmailOutbox from './EmailOutbox.svelte';
 let {data}:{data:AppData}=$props();
 let visibility=$state('internal'),body=$state(''),tab=$state('note'),busy=$state(false),error=$state(''),notice=$state('');
 const record=$derived(data.detail||{}),messages=$derived(data.related?.messages||[]),supplier=$derived(data.module?.slug==='suppliers');
 function author(message:Row){const value=message.sender_name||message.author_name;if(!value)return'Berechtigter Mitarbeiter';if(/^[a-f0-9-]{36}$/i.test(value)){const known=Object.values(data.lookups||{}).flat().find(item=>item.id===value);return known?.name||'Berechtigter Mitarbeiter';}return value;}
 async function saveMessage(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';notice='';try{await command('communication.message.create',undefined,{order_id:data.module?.slug==='orders'?record.id:record.order_id,customer_id:data.module?.slug==='customers'?record.id:record.customer_id,supplier_id:supplier?record.id:undefined,visibility,body});body='';notice=visibility==='internal'?'Die interne Notiz wurde gespeichert.':'Die Nachricht wurde im bezeichneten Kommunikationsbereich gespeichert.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Nachricht konnte nicht gespeichert werden.';}finally{busy=false;}}
</script>
<section class="panel"><header class="panel-header"><h2>Kommunikation zu diesem Vorgang</h2><Icon name="mail" size={18}/></header><div class="panel-body"><div class="tabs mb"><button class="tab" class:active={tab==='note'} onclick={()=>tab='note'}>Notiz / Nachricht</button>{#if permitted(data,'sales')||permitted(data,'billing')}<button class="tab" class:active={tab==='email'} onclick={()=>tab='email'}>E-Mail & Versand</button>{/if}</div>{#if tab==='email'}<EmailOutbox {data}/>{:else}{#if error}<div class="notice error mb" role="alert">{error}</div>{/if}{#if notice}<div class="notice info mb" role="status">{notice}</div>{/if}<form onsubmit={saveMessage}><div class="field mb"><label for="message-visibility">Bereich *</label><select use:searchableSelect={visibility} id="message-visibility" bind:value={visibility}><option value="internal">Interne Notiz</option>{#if !supplier&&permitted(data,'portal.publish')}<option value="customer">Kundenkommunikation</option>{/if}{#if supplier&&permitted(data,'purchasing')}<option value="supplier">Lieferantenkommunikation</option>{/if}</select><span class="field-help">Eine Notiz sendet keine E-Mail. Ein externer Bereich veröffentlicht nicht automatisch die gesamte Akte im Portal.</span></div><div class="field"><label for="message-body">Inhalt *</label><textarea id="message-body" bind:value={body} required maxlength="20000"></textarea></div><button class="btn primary mt" disabled={busy}>{busy?'Wird gespeichert …':'Inhalt speichern'}</button></form>{/if}</div></section>
{#if tab==='note'&&messages.length}<section class="panel"><header class="panel-header"><h2>Nachrichtenverlauf</h2><span class="count">{messages.length}</span></header><div class="panel-body">{#each messages as message}<article class="timeline-item"><h3>{({internal:'Interne Notiz',customer:'Kundennachricht',supplier:'Lieferantennachricht'} as Record<string,string>)[message.visibility]||'Nachricht'}</h3><p>{author(message)} · {display(message.created_at,'created_at')}</p><p style="white-space:pre-wrap;color:var(--ink)">{message.body}</p></article>{/each}</div></section>{/if}
